import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const easeOutClass = "ease-[cubic-bezier(0.23,1,0.32,1)]";

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

export function edgeOffset(placement: string | null, distance: number) {
  switch (placement) {
    case "top":
      return { x: 0, y: distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
    default:
      return { x: 0, y: -distance };
  }
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { createContext, type ReactNode, useContext } from "react";
import { DisclosureStateContext } from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";

export const CollapsibleIdsContext = createContext<{
  triggerId: string;
  panelId: string;
} | null>(null);

type CollapsiblePanelProps = Omit<
  HTMLMotionProps<"div">,
  | "animate"
  | "initial"
  | "transition"
  | "id"
  | "aria-hidden"
  | "inert"
  | "children"
> & { children?: ReactNode };

export function CollapsiblePanel({
  children,
  className,
  role = "group",
  ...props
}: CollapsiblePanelProps) {
  const ids = useContext(CollapsibleIdsContext);
  const isExpanded = useContext(DisclosureStateContext)?.isExpanded;
  const reduceMotion = useReducedMotion();
  if (!ids) throw new Error("CollapsiblePanel must be inside a disclosure.");

  return (
    <motion.div
      data-slot="collapsible-panel"
      {...props}
      id={ids.panelId}
      role={role}
      aria-labelledby={ids.triggerId}
      aria-hidden={!isExpanded}
      inert={!isExpanded}
      className={cn("overflow-hidden", className)}
      initial={false}
      animate={{ height: isExpanded ? "auto" : 0, opacity: isExpanded ? 1 : 0 }}
      transition={{
        height: { duration: reduceMotion ? 0 : duration.base, ease: easeOut },
        opacity: { duration: reduceMotion ? 0 : duration.fast, ease: easeOut },
      }}
    >
      {children}
    </motion.div>
  );
}

"use client";

import { CaretDownIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import { type ComponentProps, type ReactNode, useContext, useId } from "react";
import {
  Disclosure as AriaDisclosure,
  Button,
  type ButtonProps,
  composeRenderProps,
  type DisclosureProps,
  DisclosureStateContext,
  Heading,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";
import { CollapsibleIdsContext, CollapsiblePanel } from "./collapsible-panel";

export function Disclosure({
  className,
  children,
  ...props
}: DisclosureProps & React.RefAttributes<HTMLDivElement>) {
  const id = useId();
  return (
    <CollapsibleIdsContext.Provider
      value={{ triggerId: `${id}-trigger`, panelId: `${id}-panel` }}
    >
      <AriaDisclosure
        data-slot="disclosure"
        {...props}
        className={composeRenderProps(className, (className) =>
          cn(
            "min-w-0 rounded-lg border border-border bg-card text-card-foreground",
            className,
          ),
        )}
      >
        {children}
      </AriaDisclosure>
    </CollapsibleIdsContext.Provider>
  );
}

export function DisclosureHeader({
  children,
  className,
  ...props
}: Omit<ButtonProps, "children"> & { children: ReactNode }) {
  const isExpanded = useContext(DisclosureStateContext)?.isExpanded;
  const ids = useContext(CollapsibleIdsContext);
  const reduceMotion = useReducedMotion();
  return (
    <Heading className="m-0 text-sm font-semibold">
      <Button
        data-slot="disclosure-header"
        {...props}
        slot="trigger"
        id={ids?.triggerId}
        aria-controls={ids?.panelId}
        className={composeRenderProps(className, (className) =>
          cn(
            "flex min-h-11 w-full cursor-pointer items-center justify-between gap-3 rounded-lg px-4 py-2.5 text-start transition-[background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted disabled:cursor-default disabled:opacity-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
            className,
          ),
        )}
      >
        <span className="min-w-0 [overflow-wrap:anywhere]">{children}</span>
        <motion.span
          className="shrink-0 text-muted-foreground"
          aria-hidden="true"
          initial={false}
          animate={{ rotate: isExpanded ? 180 : 0 }}
          transition={{
            duration: reduceMotion ? 0 : duration.base,
            ease: easeOut,
          }}
        >
          <CaretDownIcon size={16} />
        </motion.span>
      </Button>
    </Heading>
  );
}

export function DisclosurePanel({
  className,
  children,
  ...props
}: ComponentProps<typeof CollapsiblePanel>) {
  return (
    <CollapsiblePanel
      data-slot="disclosure-panel"
      {...props}
      className={cn("text-sm leading-6 text-muted-foreground", className)}
    >
      <div className="px-4 pb-4 [overflow-wrap:anywhere]">{children}</div>
    </CollapsiblePanel>
  );
}

"use client";

import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";
import { easeInOut } from "./motion";
import { cn } from "./utils";
import { CollapsiblePanel } from "./collapsible-panel";
import { Disclosure, DisclosureHeader } from "./disclosure";

export type ToolCallStatus = "running" | "complete" | "error";

export function ToolCall({
  className,
  ...props
}: Omit<ComponentProps<typeof Disclosure>, "className"> & {
  className?: string;
}) {
  return (
    <Disclosure
      {...props}
      data-slot="tool-call"
      className={cn("min-w-0 overflow-hidden rounded-xl", className)}
    />
  );
}

export interface ToolCallTriggerProps
  extends Omit<
    ComponentProps<typeof DisclosureHeader>,
    "children" | "className"
  > {
  name: string;
  status: ToolCallStatus;
  summary?: string;
  className?: string;
}

export function ToolCallTrigger({
  name,
  status,
  summary,
  className,
  ...props
}: ToolCallTriggerProps) {
  const reduceMotion = useReducedMotion() === true;
  return (
    <DisclosureHeader
      {...props}
      data-slot="tool-call-trigger"
      className={cn(
        "min-h-14 rounded-xl px-4 py-3 hover:bg-muted/70 focus-visible:-outline-offset-2 [&>span:first-child]:min-w-0 [&>span:first-child]:flex-1",
        className,
      )}
    >
      <span className="flex min-w-0 items-center gap-3">
        <span
          aria-hidden="true"
          className={cn(
            "grid size-8 shrink-0 place-items-center rounded-lg bg-accent text-primary",
            status === "complete" && "bg-success-subtle text-success",
            status === "error" && "bg-destructive/10 text-destructive",
          )}
        >
          {status === "running" ? (
            <motion.span
              className="size-2 rounded-full bg-current forced-colors:bg-[CanvasText]"
              initial={false}
              animate={
                reduceMotion ? { opacity: 1 } : { opacity: [0.4, 1, 0.4] }
              }
              transition={
                reduceMotion
                  ? { duration: 0 }
                  : { duration: 1.2, repeat: Infinity, ease: easeInOut }
              }
            />
          ) : status === "complete" ? (
            <CheckCircleIcon size={17} />
          ) : (
            <XCircleIcon size={17} />
          )}
        </span>
        <span className="min-w-0 text-start">
          <span className="block font-mono text-xs font-semibold text-foreground [overflow-wrap:anywhere]">
            {name}
          </span>
          {summary && (
            <span className="mt-0.5 block text-xs font-normal leading-5 text-muted-foreground [overflow-wrap:anywhere]">
              {summary}
            </span>
          )}
        </span>
        <span
          aria-live="polite"
          className="ms-auto shrink-0 text-xs font-normal text-muted-foreground"
        >
          {status === "running"
            ? "Running"
            : status === "complete"
              ? "Done"
              : "Failed"}
        </span>
      </span>
    </DisclosureHeader>
  );
}

export function ToolCallPanel({
  children,
  className,
  ...props
}: ComponentProps<typeof CollapsiblePanel>) {
  return (
    <CollapsiblePanel
      data-slot="tool-call-panel"
      {...props}
      className={cn("text-sm leading-6 text-foreground", className)}
    >
      <div className="min-w-0 border-t border-border/70 px-4 pt-3 pb-4 [overflow-wrap:anywhere]">
        {children}
      </div>
    </CollapsiblePanel>
  );
}
